		envBitBucketBackups, envBitBucketCompare, envBitBucketBackupLFS,
		envAzureDevOpsUserName, envAzureDevOpsPAT, envAzureDevOpsOrgs, envAzureDevOpsCompare, envAzureDevOpsBackupLFS,
		envSourcehutToken, envSourcehutAPIURL,
	}
	clear := func() {
		for _, v := range vars {
			_ = os.Unsetenv(v)
			_ = os.Unsetenv(v + "_FILE")
		}
	}
	values := []string{"", " ", "x", "REFS", "refs", "true", "yes", "3", "Org-A,Org-B"}

	var out bytes.Buffer
	old := logger
	logger = log.New(&out, "", 0)
	defer func() { logger = old }()

	missing := filepath.Join(t.TempDir(), "nope")
	// deterministic LCG
	seed := uint64(12345)
	next := func(n int) int {
		seed = seed*6364136223846793005 + 1442695040888963407
		return int((seed >> 33) % uint64(n))
	}

	for i := 0; i < 4000; i++ {
		clear()
		var desc []string
		for _, v := range vars {
			switch next(4) {
			case 0: // unset
			case 1, 2:
				val := values[next(len(values))]
				_ = os.Setenv(v, val)
				desc = append(desc, fmt.Sprintf("%s=%q", v, val))
			case 3:
				if next(3) == 0 {
					_ = os.Setenv(v+"_FILE", missing)
					desc = append(desc, v+"_FILE=missing")
				}
			}
		}
		fmt.Fprintf(&out, "## case %d: %s\n", i, strings.Join(desc, " "))
		fmt.Fprintln(&out, "# display")
		displayStartupConfig()

		// checkProvidersDefined iterates a map; capture logs+error order-insensitively
		var sub bytes.Buffer
		logger = log.New(&sub, "", 0)
		err := checkProvidersDefined()
		logger = log.New(&out, "", 0)
		lines := strings.Split(strings.TrimSpace(sub.String()), "\n")
		sort.Strings(lines)
		fmt.Fprintf(&out, "# checkProvidersDefined logs(sorted): %q\n", lines)
		if err != nil {
			el := strings.Split(strings.TrimSpace(err.Error()), "\n")
			sort.Strings(el)
			fmt.Fprintf(&out, "# err(sorted): %q\n", el)
		} else {
			fmt.Fprintln(&out, "# err: nil")
		}
		for _, p := range []string{providerNameGitHub, providerNameGitLab, providerNameGitea, providerNameSourcehut, providerNameAzureDevOps, providerNameBitBucketAPIToken, providerNameBitBucketOAuth} {
			var s2 bytes.Buffer
			logger = log.New(&s2, "", 0)
			n, e := checkProvider(p)
			logger = log.New(&out, "", 0)
			fmt.Fprintf(&out, "# checkProvider(%s)=%d err=%v logs=%q\n", p, n, e, s2.String())
		}
	}
	clear()
	if err := os.WriteFile(os.Getenv("ZZ_OUT"), []byte(strings.ReplaceAll(out.String(), missing, "<missing>")), 0o600); err != nil {
		t.Fatal(err)
	}
}
