// allAuthParamsDefined reports whether all of the provider's auth parameters
// are set, recording the missing ones when only some are.
func allAuthParamsDefined(provider string, errs *strings.Builder) bool {
	var foundCount, totalCount int

	for _, param := range enabledProviderAuth[provider] {
		totalCount++

		val, exists := GetEnvOrFile(param)
		if exists && strings.Trim(val, " ") != "" {
			foundCount++
		}
